Action: run_sql({'query': "WITH recent_inspections AS (\n    SELECT \n        i.slchd_establishment_key,\n        i.inspection_date,\n        SUM(v.violation_occurrences) as critical_violations\n    FROM inspections i\n    JOIN violations v ON i.inspection_id = v.inspection_id\n    JOIN violation_codes vc ON v.violation_code_id = vc.violation_code_id\n    WHERE vc.critical = TRUE\n      AND i.inspection_date >= '2021-01-01'\n    GROUP BY 1, 2\n),\nranked_inspections AS (\n    SELECT \n        slchd_establishment_key,\n        inspection_date,\n        critical_violations,\n        LAG(critical_violations) OVER (PARTITION BY slchd_establishment_key ORDER BY inspection_date ASC) as prev_critical_violations,\n        ROW_NUMBER() OVER (PARTITION BY slchd_establishment_key ORDER BY inspection_date DESC) as recency_rank\n    FROM recent_inspections\n)\nSELECT \n    e.name,\n    r.inspection_date as latest_inspection_date,\n    r.critical_violations as latest_critical_violations,\n    r.prev_critical_violations as previous_critical_violations,\n    (r.critical_violations - r.prev_critical_violations) as change\nFROM ranked_inspections r\nJOIN establishments e ON r.slchd_establishment_key = e.slchd_establishment_key\nWHERE r.recency_rank = 1 \n  AND r.prev_critical_violations IS NOT NULL\nORDER BY change DESC\nLIMIT 20;"})

